#!/usr/bin/env bash
# Build paper/main.pdf with a pinned Tectonic (downloaded to .tools/ if missing) and the
# Markdown mirror paper/paper.md and the web reader docs/paper/ with pandoc. Tables and figures must already have been
# generated by `make experiments`.
set -euo pipefail
cd "$(dirname "$0")"
ROOT=$(cd .. && pwd)
VERSION=0.16.9
SHA256=60b13a0826ae7ad9ce34b4a2df06bff2cfcfa6dda8a915477c0cbb84e1a4a902
TECTONIC="$ROOT/.tools/tectonic"
if [ ! -x "$TECTONIC" ]; then
  mkdir -p "$ROOT/.tools"
  curl -fsSL -o "$ROOT/.tools/tectonic.tar.gz" \
    "https://github.com/tectonic-typesetting/tectonic/releases/download/tectonic%40${VERSION}/tectonic-${VERSION}-x86_64-unknown-linux-musl.tar.gz"
  echo "${SHA256}  $ROOT/.tools/tectonic.tar.gz" | sha256sum -c -
  tar -xzf "$ROOT/.tools/tectonic.tar.gz" -C "$ROOT/.tools"
fi
"$TECTONIC" --keep-logs --outdir . main.tex
if command -v pandoc >/dev/null; then
  # IEEEtran title/abstract and PDF figures need a small rewrite for the GitHub mirror.
  python3 md_mirror.py || echo "pandoc mirror failed (PDF is still built)"
  # Web reader docs/paper/ (served by mkdocs at /paper/).
  python3 web.py
else
  echo "pandoc not found: paper/paper.md not rebuilt"
fi
echo "built $(pwd)/main.pdf"
